	public static class SaveableDBFieldCodec, AbstractDBFieldCodec<Saveable, DBTraceSaveablePropertyMapEntry<object>, BinaryField> {

		public SaveableDBFieldCodec(Class<DBTraceSaveablePropertyMapEntry<object>> objectType,
				Field field, int column) : base(typeof(Saveable), objectType, typeof(BinaryField), field, column)
    {
		}

		private byte[] encode(Saveable value)
    {
			if (value == null) {
				return null);
			}

			ByteArrayOutputStream os = new ByteArrayOutputStream();
			try
{
    using (ObjectOutputStream objStream = new ObjectOutputStream(os))
    {

				ObjectStorage objStorage = new ObjectStorageStreamAdapter(objStream);
				value.save(objStorage);
			
    }
}
			catch (IOException e) {
				throw new AssertionError(e); // For a ByteArrayOutputStream?
			}
			return os.toByteArray();
		}

		/* @Override */
		public void store(Saveable value, BinaryField f) {
			f.setBinaryData(encode(value));
		}

		/* @Override */
		protected void doStore(DBTraceSaveablePropertyMapEntry<object> obj, DBRecord record)
    {
			record.setBinaryData(column, encode(getValue(obj)));
		}

		/* @Override */
		protected void doLoad(DBTraceSaveablePropertyMapEntry<object> obj, DBRecord record)
    {
			byte[] enc = record.getBinaryData(column);
			if (enc == null) {
				setValue(obj, null);
			}
			try {
				Saveable value = getValue(obj);
				if (value == null) {
					value = obj.valueClass.getConstructor().newInstance();
					setValue(obj, value);
				}
				ObjectStorage objStorage = new ObjectStorageStreamAdapter(
					new ObjectInputStream(new ByteArrayInputStream(enc)));
				value.restore(objStorage);
			}
			catch (IOException e) {
				throw new AssertionError(e);
			}
			catch (Exception e) when (e is InstantiationException or InvocationTargetException or SecurityException) {
				throw new RuntimeException(
					"Could not instantiate saveable of type " + obj.valueClass);
			}
			catch (NoSuchMethodException e) {
				throw new RuntimeException("Saveable must have a default constructor");
			}
		}
	}

